void Solver::restart() {
    fast_lbd_sum = lbd_queue_size = lbd_queue_pos = 0;
    backtrack(0);

    int phase_rand = rand() % 100;
    if (phase_rand < 60) {
        for (int i = 1; i <= vars; i++) {
            saved[i] = trail.size() > 0 ? value[i] : local_best[i];
        }
    }
    else if (phase_rand < 85) {
        for (int i = 1; i <= vars; i++) {
            saved[i] = rand() % 2 ? 1 : -1;
        }
    }
    else {
        for (int i = 1; i <= vars; i++) {
            saved[i] = -local_best[i];
        }
    }
}
